package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.entity.Statuses.ShipmentStatus; import com.shiphappens.logistics.service.LogisticsService; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/v1/dashboard") public class DashboardController { private final LogisticsService service; public DashboardController(LogisticsService service){this.service=service;} @GetMapping public Map<String,Long> metrics(){return Map.of("activeShipments",service.count(ShipmentStatus.CREATED)+service.count(ShipmentStatus.PICKED_UP)+service.count(ShipmentStatus.IN_TRANSIT)+service.count(ShipmentStatus.AT_WAREHOUSE)+service.count(ShipmentStatus.OUT_FOR_DELIVERY),"inTransit",service.count(ShipmentStatus.IN_TRANSIT),"outForDelivery",service.count(ShipmentStatus.OUT_FOR_DELIVERY),"delivered",service.count(ShipmentStatus.DELIVERED),"failed",service.count(ShipmentStatus.FAILED));} }
